 Here's a Dart function that takes a list of `Transaction` objects as an argument and returns a map containing the top three coins with the highest average profit and the top three coins with the highest average loss:

```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss; // positive for profit, negative for loss

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, dynamic> topCoins(List<Transaction> transactions) {
  Map<String, double> profitSumMap = {};
  Map<String, int> profitCountMap = {};
  Map<String, double> lossSumMap = {};
  Map<String, int> lossCountMap = {};

  for (Transaction transaction in transactions) {
    if (transaction.profitLoss > 0) {
      profitSumMap[transaction.coinName] = (profitSumMap[transaction.coinName] ?? 0) + transaction.profitLoss;
      profitCountMap[transaction.coinName] = (profitCountMap[transaction.coinName] ?? 0) + 1;
    } else {
      lossSumMap[transaction.coinName] = (lossSumMap[transaction.coinName] ?? 0) + transaction.profitLoss;
      lossCountMap[transaction.coinName] = (lossCountMap[transaction.coinName] ?? 0) + 1;
    }
  }

  var sortedProfitCoins = profitSumMap.entries.map((entry) => MapEntry(entry.key, entry.value / profitCountMap[entry.key]!));
  var sortedLossCoins = lossSumMap.entries.map((entry) => MapEntry(entry.key, entry.value / lossCountMap[entry.key]!));

  return {
    "top_three_profitable_coins": List.from(sortedProfitCoins.take(3)),
    "top_three_unprofitable_coins": List.from(sortedLossCoins.take(3))
  };
}
```

