public static double calculateTotalMagneticField(double[] locationData) {
    double latitude = locationData[0];
    double longitude = locationData[1];
    double magneticIntensity = locationData[2];
    return Math.sqrt(Math.pow(latitude, 2) + Math.pow(longitude, 2) + Math.pow(magneticIntensity, 2));
}
