function switchAdjectiveOrder(sentence) {
  // Split the sentence into words and identify adjectives using a part-of-speech tagger or a predefined list of common adjectives
  const words = sentence.split(' ');
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {
      adjectives.push(words[i]);
      words.splice(i, 1); // remove the identified adjective from the original array
      i--; // adjust index since length of words array has changed
    }
  }

  // Reverse the order of adjectives and insert them back into the sentence
  const reversedAdjectives = [...adjectives].reverse();

  for (let j = 0; j < reversedAdjectives.length; j++) {
    words.unshift(reversedAdjectives[j]);
  }

  return words.join(' ') + '.';
}

